def maximize_sweetness_brute(sweetness, k):
    n = len(sweetness)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + sweetness[i]

    def helper(start, pieces_left):
        if pieces_left == 1:
            return prefix[n] - prefix[start]               # remaining sum is the last piece
        best = -1
        for end in range(start + 1, n - pieces_left + 2):     # try every cut point
            piece_sum = prefix[end] - prefix[start]
            best = max(best, min(piece_sum, helper(end, pieces_left - 1)))
        return best

    return helper(0, k + 1)

