def maximize_sweetness(sweetness, k):
    def pieces_achievable(min_sweet):
        count, current = 0, 0
        for s in sweetness:
            current += s
            if current >= min_sweet:                # cut off a piece as soon as it qualifies
                count += 1
                current = 0
        return count

    lo, hi = min(sweetness), sum(sweetness) // (k + 1)
    while lo < hi:
        mid = lo + (hi - lo + 1) // 2               # bias mid upward to search for the max feasible
        if pieces_achievable(mid) >= k + 1:
            lo = mid                                   # feasible, try an even higher threshold
        else:
            hi = mid - 1                                # infeasible, need a lower threshold
    return lo

