public class Main {
    static int piecesAchievable(int[] sweetness, int minSweet) {
        int count = 0, current = 0;
        for (int s : sweetness) {
            current += s;
            if (current >= minSweet) { count++; current = 0; }   // cut off as soon as it qualifies
        }
        return count;
    }

    static int maximizeSweetness(int[] sweetness, int k) {
        int lo = Integer.MAX_VALUE, total = 0;
        for (int s : sweetness) { lo = Math.min(lo, s); total += s; }
        int hi = total / (k + 1);
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;                       // bias upward
            if (piecesAchievable(sweetness, mid) >= k + 1) lo = mid;    // feasible, try higher
            else hi = mid - 1;                                            // infeasible, go lower
        }
        return lo;
    }
}

